    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Particle color\",\"default\":\"#38bdf8\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#020617\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #020617;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #020617;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n        overflow: hidden;\n      }\n      #stage {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"particles-grid\"\n      data-start=\"0\"\n      data-duration=\"6.67\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"6.67\" style=\"position:absolute;inset:0;background-color:#020617\"></div>\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"6.67\" style=\"position:absolute;inset:0;width:100%;height:100%;z-index:1\"></canvas>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const canvas = document.getElementById(\"stage\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const cols = 20;\n        const rows = 12;\n        const cellW = view.width / cols;\n        const cellH = view.height / rows;\n        const simulator = hyperbits.createParticles({\n          fps: 30,\n          spawners: [{\n            id: \"grid\",\n            burst: cols * rows,\n            startFrame: 1,\n            position: { x: view.width / 2, y: view.height / 2 },\n            area: { width: 0, height: 0 },\n            velocity: { x: 0, y: 0 },\n            lifespan: 220,\n            max: cols * rows,\n          }],\n          behaviors: [{\n            id: \"lattice\",\n            handler: function (particle, age) {\n              const col = particle.index % cols;\n              const row = Math.floor(particle.index / cols);\n              particle.position.x = cellW * (col + 0.5);\n              particle.position.y = cellH * (row + 0.5);\n              particle.opacity = 0.35 + 0.65 * (0.5 + 0.5 * Math.sin(age * 0.12 + col * 0.45 + row * 0.35));\n            },\n          }],\n        });\n        const timeline = gsap.timeline({ paused: true });\n        hyperbits.bind(timeline, canvas, simulator, {\n          color: vars.color,\n          size: view.vmin * 1.4,\n          glow: 1.2,\n          shape: \"circle\",\n        });\n        timeline.fromTo(canvas, { x: 0 }, { x: 0.5, duration: 6.67, ease: \"none\" }, 0);\n        registerTimeline(\"particles-grid\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
