    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Card color\",\"default\":\"#38bdf8\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#020617\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #020617;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #020617;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n        overflow: hidden;\n      }\n      #world {\n        position: absolute;\n        inset: 0;\n        z-index: 1;\n        overflow: hidden;\n      }\n      .col {\n        position: absolute;\n        top: 0;\n        height: 100%;\n        overflow: hidden;\n      }\n      .track {\n        display: flex;\n        flex-direction: column;\n        width: 100%;\n      }\n      .card {\n        width: 100%;\n        flex: 0 0 auto;\n        overflow: hidden;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        color: #f8fafc;\n        font-weight: 700;\n        font-size: 4vmin;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"scrolling-columns\"\n      data-start=\"0\"\n      data-duration=\"10\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"10\" style=\"position:absolute;inset:0;background-color:#020617\"></div>\n      <div id=\"world\" class=\"clip\" data-start=\"0\" data-duration=\"10\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const world = document.getElementById(\"world\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        bg.style.setProperty(\"--knob-color\", vars.color);\n        world.style.setProperty(\"--knob-color\", vars.color);\n        const columnCount = 4;\n        const palette = [\"#1e3a8a\", \"#1d4ed8\", \"#0f766e\", \"#9a3412\", \"#6d28d9\", \"#be123c\", \"#0369a1\"];\n        const speeds = [0.42, 0.68, 0.33, 0.55];\n        const columns = [];\n        const cardHeight = view.height / 3;\n        const cardsPerColumn = 18;\n        for (let col = 0; col < columnCount; col += 1) {\n          const left = Math.round((col * view.width) / columnCount);\n          const next = Math.round(((col + 1) * view.width) / columnCount);\n          const column = document.createElement(\"div\");\n          column.className = \"col\";\n          column.style.left = left + \"px\";\n          column.style.width = next - left + \"px\";\n          column.style.backgroundColor = vars.background;\n          const track = document.createElement(\"div\");\n          track.className = \"track\";\n          for (let cardIndex = 0; cardIndex < cardsPerColumn; cardIndex += 1) {\n            const card = document.createElement(\"div\");\n            card.className = \"card\";\n            card.setAttribute(\"data-layout-allow-overlap\", \"\");\n            card.setAttribute(\"data-layout-allow-occlusion\", \"\");\n            card.setAttribute(\"data-layout-allow-overflow\", \"\");\n            card.style.height = cardHeight + \"px\";\n            card.style.fontSize = view.vmin * 4 + \"px\";\n            card.style.backgroundColor = palette[hyperbits.randomInt(\"c-\" + col + \"-\" + cardIndex, 0, palette.length - 1)];\n            card.style.color = \"#f8fafc\";\n            card.style.textShadow = \"0 2px 10px rgba(0,0,0,0.65)\";\n            card.style.boxShadow = \"inset 0 0 0 \" + Math.max(2, view.vmin * 0.25) + \"px \" + vars.color;\n            card.textContent = String(hyperbits.randomInt(\"n-\" + col + \"-\" + cardIndex, 1, 9));\n            track.append(card);\n          }\n          column.append(track);\n          world.append(column);\n          columns.push({ track: track, speed: speeds[col] });\n        }\n        const proxy = { t: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, {\n          t: 10,\n          duration: 10,\n          ease: \"none\",\n          onUpdate: function () {\n            columns.forEach(function (column) {\n              column.track.style.transform = \"translateY(\" + -proxy.t * column.speed * view.height * 0.55 + \"px)\";\n            });\n          },\n        }, 0);\n        registerTimeline(\"scrolling-columns\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
