    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#38bdf8\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#020617\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #020617;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #020617;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #scene {\n        position: absolute;\n        inset: 0;\n        z-index: 1;\n      }\n      .word {\n        color: #f8fafc;\n        font-weight: 800;\n        letter-spacing: -0.05em;\n        white-space: nowrap;\n        line-height: 1;\n        font-size: 10vmin;\n        text-align: center;\n      }\n      .word[data-step-active=\"false\"] {\n        opacity: 0;\n      }\n      .word[data-step-active=\"true\"] {\n        opacity: 1;\n      }\n      .plane {\n        width: 18vmin;\n        height: 18vmin;\n        border-radius: 1.4vmin;\n        border: 0.28vmin solid rgba(248, 250, 252, 0.18);\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"3d-elements\"\n      data-start=\"0\"\n      data-duration=\"6.67\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"6.67\" style=\"position:absolute;inset:0;background-color:#020617\"></div>\n      <div id=\"scene\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const sceneEl = document.getElementById(\"scene\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        bg.setAttribute(\"data-color\", vars.color);\n\n        const words = [\"Fly\", \"Your\", \"Camera\", \"Through\", \"Space\"];\n        const steps = words.map(function (word, index) {\n          const node = document.createElement(\"h1\");\n          node.className = \"word\";\n          node.textContent = word;\n          node.style.fontSize = view.vmin * 10 + \"px\";\n          node.style.color = vars.color;\n          node.setAttribute(\"data-layout-allow-overlap\", \"\");\n          node.setAttribute(\"data-layout-allow-occlusion\", \"\");\n          return {\n            id: \"step-\" + index,\n            x: (index - 2) * view.vmin * 36,\n            y: (index % 2 === 0 ? -1 : 1) * view.vmin * 6,\n            z: index * view.vmin * 18,\n            rotateY: (index - 2) * 10,\n            duration: 6.67 / words.length,\n            element: node,\n          };\n        });\n\n        const palette = [vars.color, \"#f472b6\", \"#f59e0b\", \"#34d399\", \"#a78bfa\", \"#fb7185\"];\n        const planeSize = view.vmin * 18;\n        const elements = [];\n        for (let index = 0; index < 8; index += 1) {\n          const plane = document.createElement(\"div\");\n          plane.className = \"plane\";\n          plane.style.width = planeSize + \"px\";\n          plane.style.height = planeSize + \"px\";\n          plane.style.backgroundColor = palette[index % palette.length];\n          plane.style.opacity = \"0.55\";\n          plane.setAttribute(\"data-layout-allow-overlap\", \"\");\n          plane.setAttribute(\"data-layout-allow-occlusion\", \"\");\n          elements.push({\n            element: plane,\n            centered: true,\n            x: hyperbits.randomFloat(\"el-x-\" + index, -view.vmin * 48, view.vmin * 48),\n            y: hyperbits.randomFloat(\"el-y-\" + index, -view.vmin * 28, view.vmin * 28),\n            z: hyperbits.randomFloat(\"el-z-\" + index, -view.vmin * 20, view.vmin * 90),\n            rotateY: hyperbits.randomFloat(\"el-ry-\" + index, -24, 24),\n            rotateX: hyperbits.randomFloat(\"el-rx-\" + index, -16, 16),\n          });\n        }\n\n        const scene = hyperbits.createScene3D(sceneEl, {\n          perspective: 1000,\n          transitionDuration: 1.05,\n          easing: \"easeInOutCubic\",\n          steps: steps,\n          elements: elements,\n        });\n        sceneEl.style.position = \"absolute\";\n        sceneEl.style.inset = \"0\";\n        sceneEl.style.zIndex = \"1\";\n\n        const timeline = gsap.timeline({ paused: true });\n        scene.bind(timeline);\n        timeline.to({}, { duration: 6.67 }, 0);\n        registerTimeline(\"3d-elements\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
