    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#38bdf8\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#0b1220\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #0b1220;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #0b1220;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #scene {\n        position: absolute;\n        inset: 0;\n        z-index: 1;\n      }\n      .card {\n        width: 32vmin;\n        height: 42vmin;\n        border-radius: 2.2vmin;\n        display: flex;\n        align-items: flex-end;\n        color: #f8fafc;\n        font-weight: 800;\n        padding: 2.2vmin;\n        box-sizing: border-box;\n        letter-spacing: -0.04em;\n        font-size: 6vmin;\n        border: 0.28vmin solid rgba(248, 250, 252, 0.16);\n        box-shadow: 0 1.6vmin 4vmin rgba(0, 0, 0, 0.45);\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"carousel\"\n      data-start=\"0\"\n      data-duration=\"10\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"10\" style=\"position:absolute;inset:0;background-color:#0b1220\"></div>\n      <div id=\"scene\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const sceneEl = document.getElementById(\"scene\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        bg.setAttribute(\"data-color\", vars.color);\n\n        const labels = [\"North\", \"Atlas\", \"Signal\", \"Harbor\", \"Nova\", \"Prism\"];\n        const colors = [vars.color, \"#0f766e\", \"#9a3412\", \"#6d28d9\", \"#be123c\", \"#0369a1\"];\n        const radius = view.vmin * 48;\n        const cardW = view.vmin * 32;\n        const cardH = view.vmin * 42;\n\n        const elements = labels.map(function (label, index) {\n          const card = document.createElement(\"div\");\n          card.className = \"card\";\n          card.textContent = label;\n          card.style.width = cardW + \"px\";\n          card.style.height = cardH + \"px\";\n          card.style.backgroundColor = colors[index];\n          card.style.fontSize = view.vmin * 6 + \"px\";\n          card.style.borderColor = vars.color;\n          card.setAttribute(\"data-layout-allow-overlap\", \"\");\n          card.setAttribute(\"data-layout-allow-occlusion\", \"\");\n          const angle = (index / labels.length) * Math.PI * 2;\n          return {\n            element: card,\n            centered: true,\n            x: Math.sin(angle) * radius,\n            z: Math.cos(angle) * radius,\n            rotateY: (index / labels.length) * 360,\n          };\n        });\n\n        const steps = labels.map(function (_label, index) {\n          return {\n            id: \"c\" + index,\n            rotateY: -(index / labels.length) * 360,\n            rotateX: 8,\n            z: view.vmin * 8,\n            duration: 10 / labels.length,\n          };\n        });\n\n        const scene = hyperbits.createScene3D(sceneEl, {\n          perspective: 1400,\n          transitionDuration: 1.45,\n          easing: \"easeInOutCubic\",\n          steps: steps,\n          elements: elements,\n        });\n        sceneEl.style.position = \"absolute\";\n        sceneEl.style.inset = \"0\";\n        sceneEl.style.zIndex = \"1\";\n\n        const timeline = gsap.timeline({ paused: true });\n        scene.bind(timeline);\n        timeline.to({}, { duration: 10 }, 0);\n        registerTimeline(\"carousel\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
