    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#38bdf8\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#020617\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #020617;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #020617;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #scene {\n        position: absolute;\n        inset: 0;\n        z-index: 1;\n      }\n      .face {\n        width: 40vmin;\n        height: 40vmin;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        color: #f8fafc;\n        font-weight: 800;\n        overflow: hidden;\n        box-sizing: border-box;\n        padding: 4vmin;\n        letter-spacing: -0.04em;\n        font-size: 8vmin;\n        box-shadow: inset 0 0 4vmin rgba(0, 0, 0, 0.35);\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"cube-navigation\"\n      data-start=\"0\"\n      data-duration=\"16\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"16\" style=\"position:absolute;inset:0;background-color:#020617\"></div>\n      <div id=\"scene\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const sceneEl = document.getElementById(\"scene\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        bg.setAttribute(\"data-color\", vars.color);\n\n        const size = view.vmin * 40;\n        const half = size / 2;\n        const faces = [\n          { id: \"front\", name: \"TEXT\", color: \"#1e293b\", x: 0, y: 0, z: half, rotateX: 0, rotateY: 0, rotateZ: 0 },\n          { id: \"right\", name: \"MOTION\", color: \"#0f766e\", x: half, y: 0, z: 0, rotateX: 0, rotateY: 90, rotateZ: 0 },\n          { id: \"back\", name: \"PARTICLES\", color: \"#9a3412\", x: 0, y: 0, z: -half, rotateX: 0, rotateY: 180, rotateZ: 0 },\n          { id: \"left\", name: \"GRADIENTS\", color: \"#6d28d9\", x: -half, y: 0, z: 0, rotateX: 0, rotateY: -90, rotateZ: 0 },\n          { id: \"top\", name: \"3D\", color: vars.color, x: 0, y: -half, z: 0, rotateX: 90, rotateY: 0, rotateZ: 0 },\n          { id: \"bottom\", name: \"BITS\", color: vars.color, x: 0, y: half, z: 0, rotateX: -90, rotateY: 0, rotateZ: 0 },\n        ];\n\n        const elements = faces.map(function (face) {\n          const node = document.createElement(\"div\");\n          node.className = \"face\";\n          node.textContent = face.name;\n          node.style.width = size + \"px\";\n          node.style.height = size + \"px\";\n          node.style.backgroundColor = face.color;\n          node.style.color = \"#f8fafc\";\n          node.style.fontSize = view.vmin * 5 + \"px\";\n          node.setAttribute(\"data-layout-allow-overlap\", \"\");\n          node.setAttribute(\"data-layout-allow-occlusion\", \"\");\n          node.style.border = size * 0.02 + \"px solid \" + vars.color;\n          node.setAttribute(\"data-layout-allow-overlap\", \"\");\n          node.setAttribute(\"data-layout-allow-occlusion\", \"\");\n          return {\n            element: node,\n            centered: true,\n            x: face.x,\n            y: face.y,\n            z: face.z,\n            rotateX: face.rotateX,\n            rotateY: face.rotateY,\n            rotateZ: face.rotateZ,\n          };\n        });\n\n        const steps = [\n          { id: \"front\", rotateY: 0, z: view.vmin * 8, duration: 16 / 6 },\n          { id: \"right\", rotateY: -90, z: view.vmin * 8, duration: 16 / 6 },\n          { id: \"back\", rotateY: -180, z: view.vmin * 8, duration: 16 / 6 },\n          { id: \"left\", rotateY: -270, z: view.vmin * 8, duration: 16 / 6 },\n          { id: \"top\", rotateX: -90, z: view.vmin * 8, duration: 16 / 6 },\n          { id: \"bottom\", rotateX: 90, z: view.vmin * 8, duration: 16 / 6 },\n        ];\n\n        const scene = hyperbits.createScene3D(sceneEl, {\n          perspective: 2000,\n          transitionDuration: 2.2,\n          easing: \"easeInOutCubic\",\n          steps: steps,\n          elements: elements,\n        });\n        sceneEl.style.position = \"absolute\";\n        sceneEl.style.inset = \"0\";\n        sceneEl.style.zIndex = \"1\";\n\n        const timeline = gsap.timeline({ paused: true });\n        scene.bind(timeline);\n        timeline.to({}, { duration: 16 }, 0);\n        registerTimeline(\"cube-navigation\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
