    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"words\",\"type\":\"string\",\"label\":\"Words\",\"default\":\"SEEK,FRAME,MOTION,SCALE,DEPTH,LIGHT,TIME,SPACE\"},{\"id\":\"color\",\"type\":\"color\",\"label\":\"Text color\",\"default\":\"#e2e8f0\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#000000\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #000000;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #000000;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #scene {\n        position: absolute;\n        inset: 0;\n        z-index: 1;\n      }\n      .word {\n        color: #e2e8f0;\n        font-weight: 800;\n        letter-spacing: 0.08em;\n        white-space: nowrap;\n        line-height: 1;\n        font-size: 8vmin;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"flying-through-words\"\n      data-start=\"0\"\n      data-duration=\"10\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"10\" style=\"position:absolute;inset:0;background-color:#000000\"></div>\n      <div id=\"scene\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const sceneEl = document.getElementById(\"scene\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        bg.setAttribute(\"data-color\", vars.color);\n\n        const list = String(vars.words).split(\",\").map(function (part) { return part.trim(); }).filter(Boolean);\n        const slots = [\n          { x: -22, y: -10 },\n          { x: 24, y: 12 },\n          { x: -18, y: 16 },\n          { x: 20, y: -14 },\n          { x: -26, y: 8 },\n          { x: 14, y: 18 },\n          { x: -12, y: -18 },\n          { x: 22, y: 4 },\n        ];\n        const depth = view.vmin * 40;\n        const count = Math.max(list.length, slots.length);\n        const elements = [];\n        for (let index = 0; index < Math.min(count, slots.length); index += 1) {\n          const node = document.createElement(\"div\");\n          node.className = \"word\";\n          node.textContent = list[index % list.length];\n          node.style.fontSize = view.vmin * 8 + \"px\";\n          node.style.color = vars.color;\n          node.setAttribute(\"data-layout-allow-overlap\", \"\");\n          node.setAttribute(\"data-layout-allow-occlusion\", \"\");\n          elements.push({\n            element: node,\n            centered: true,\n            x: slots[index].x * view.vmin,\n            y: slots[index].y * view.vmin,\n            z: (index + 1) * depth,\n          });\n        }\n\n        const stepCount = 7;\n        const steps = [];\n        for (let index = 0; index < stepCount; index += 1) {\n          steps.push({\n            id: \"z\" + index,\n            x: 0,\n            y: 0,\n            z: index * depth + view.vmin * 8,\n            duration: 10 / stepCount,\n          });\n        }\n\n        const scene = hyperbits.createScene3D(sceneEl, {\n          perspective: 900,\n          transitionDuration: 1.28,\n          easing: \"easeInOutCubic\",\n          steps: steps,\n          elements: elements,\n        });\n        sceneEl.style.position = \"absolute\";\n        sceneEl.style.inset = \"0\";\n        sceneEl.style.zIndex = \"1\";\n\n        const timeline = gsap.timeline({ paused: true });\n        scene.bind(timeline);\n        timeline.to({}, { duration: 10 }, 0);\n        registerTimeline(\"flying-through-words\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
