    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#38bdf8\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#111827\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #111827;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #111827;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #scene {\n        position: absolute;\n        inset: 0;\n        z-index: 1;\n        overflow: hidden;\n      }\n      #plane {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        object-fit: cover;\n        transform-origin: center center;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"ken-burns\"\n      data-start=\"0\"\n      data-duration=\"10\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"10\" style=\"position:absolute;inset:0;background-color:#111827\"></div>\n      <div id=\"scene\">\n        <div id=\"plane\"></div>\n      </div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const plane = document.getElementById(\"plane\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        bg.setAttribute(\"data-color\", vars.color);\n        plane.style.backgroundImage = \"linear-gradient(135deg, \" + vars.background + \" 0%, \" + vars.color + \" 48%, #f59e0b 100%)\";\n        plane.style.backgroundSize = \"cover\";\n        plane.style.backgroundPosition = \"center\";\n\n        const timeline = gsap.timeline({ paused: true });\n        timeline.fromTo(\n          plane,\n          { scale: 1.05, x: 0, y: 0 },\n          { scale: 1.25, x: view.vmin * 8, y: -view.vmin * 6, duration: 10, ease: \"none\" },\n          0\n        );\n        registerTimeline(\"ken-burns\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
