    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"title\",\"type\":\"string\",\"label\":\"Title\",\"default\":\"Enter\"},{\"id\":\"color\",\"type\":\"color\",\"label\":\"Text color\",\"default\":\"#f8fafc\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#0f172a\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #0f172a;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #0f172a;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #scene {\n        position: absolute;\n        inset: 0;\n        z-index: 1;\n      }\n      .slide {\n        text-align: center;\n        width: 70vmin;\n      }\n      .slide h1 {\n        font-weight: 800;\n        letter-spacing: -0.05em;\n        line-height: 1.05;\n        font-size: 8vmin;\n        color: #f8fafc;\n      }\n      .slide p {\n        margin-top: 0.35em;\n        color: #cbd5e1;\n        font-size: 3.2vmin;\n        font-weight: 600;\n      }\n      .slide[data-step-active=\"false\"] {\n        opacity: 0;\n      }\n      .slide[data-step-active=\"true\"] {\n        opacity: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"step-timing-context\"\n      data-start=\"0\"\n      data-duration=\"10\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"10\" style=\"position:absolute;inset:0;background-color:#0f172a\"></div>\n      <div id=\"scene\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const sceneEl = document.getElementById(\"scene\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        bg.setAttribute(\"data-color\", vars.color);\n\n        function slide(titleText, bodyText) {\n          const wrap = document.createElement(\"div\");\n          wrap.className = \"slide\";\n          wrap.style.width = view.vmin * 70 + \"px\";\n          const title = document.createElement(\"h1\");\n          title.textContent = titleText;\n          title.style.fontSize = view.vmin * 8 + \"px\";\n          title.style.color = vars.color;\n          const body = document.createElement(\"p\");\n          body.textContent = bodyText;\n          body.style.fontSize = view.vmin * 3.2 + \"px\";\n          wrap.append(title, body);\n          wrap.setAttribute(\"data-layout-allow-overlap\", \"\");\n          wrap.setAttribute(\"data-layout-allow-occlusion\", \"\");\n          return wrap;\n        }\n\n        const first = slide(String(vars.title), \"Copy settles.\");\n        const second = slide(\"Hold\", \"Motion waits.\");\n        const third = slide(\"Leave\", \"Exit starts.\");\n        const fourth = slide(\"Time\", \"Steps own the clock.\");\n        const depth = view.vmin * 70;\n        const hold = 10 / 4;\n\n        const scene = hyperbits.createScene3D(sceneEl, {\n          perspective: 1100,\n          transitionDuration: 0.85,\n          easing: \"easeInOutCubic\",\n          steps: [\n            { id: \"enter\", x: 0, y: 0, z: 0, duration: hold, element: first },\n            { id: \"hold\", x: 0, y: view.vmin * 4, z: depth, duration: hold, element: second },\n            { id: \"leave\", x: 0, y: view.vmin * 8, z: depth * 2, duration: hold, element: third },\n            { id: \"time\", x: 0, y: view.vmin * 12, z: depth * 3, duration: hold, element: fourth },\n          ],\n        });\n        sceneEl.style.position = \"absolute\";\n        sceneEl.style.inset = \"0\";\n        sceneEl.style.zIndex = \"1\";\n\n        const timeline = gsap.timeline({ paused: true });\n        scene.bind(timeline);\n        [first, second, third, fourth].forEach(function (node, index) {\n          const words = hyperbits.splitText(node.querySelector(\"h1\"), \"words\");\n          hyperbits.stagger(words, {\n            opacity: [0, 1],\n            y: [18, 0],\n            duration: 0.4,\n            stagger: 0.05,\n            delay: index * hold,\n            ease: \"easeOutCubic\",\n          }, timeline);\n        });\n        timeline.to({}, { duration: 10 }, 0);\n        registerTimeline(\"step-timing-context\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
