    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"command\",\"type\":\"string\",\"label\":\"Command\",\"default\":\"git status\"},{\"id\":\"color\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#86efac\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#020617\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #020617;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #020617;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #scene {\n        position: absolute;\n        inset: 0;\n        z-index: 1;\n      }\n      .term[data-step-active=\"false\"] {\n        opacity: 0.12;\n      }\n      .term[data-step-active=\"true\"] {\n        opacity: 1;\n      }\n      .term {\n        width: 40%;\n        height: 50%;\n        background-color: #0b1220;\n        border: 1px solid #1e293b;\n        border-radius: 1.4vmin;\n        overflow: hidden;\n        display: flex;\n        flex-direction: column;\n        box-shadow: 0 1.6vmin 4vmin rgba(0, 0, 0, 0.45);\n      }\n      .term-bar {\n        height: 12%;\n        background-color: #1e293b;\n        display: flex;\n        align-items: center;\n        padding: 0 3%;\n        gap: 0.8vmin;\n      }\n      .term-dot {\n        width: 1.2vmin;\n        height: 1.2vmin;\n        border-radius: 50%;\n      }\n      .term-title {\n        flex: 1;\n        text-align: center;\n        color: #94a3b8;\n        font-size: 2vmin;\n        font-weight: 600;\n      }\n      .term-body {\n        flex: 1;\n        padding: 4%;\n        color: #86efac;\n        font-family: \"JetBrains Mono\", ui-monospace, monospace;\n        font-size: 3vmin;\n        line-height: 1.45;\n        white-space: pre;\n        overflow: hidden;\n      }\n      .cursor {\n        display: inline-block;\n        width: 0.55em;\n        background-color: #86efac;\n        margin-left: 0.06em;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"terminal-3d\"\n      data-start=\"0\"\n      data-duration=\"10\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"10\" style=\"position:absolute;inset:0;background-color:#020617\"></div>\n      <div id=\"scene\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const sceneEl = document.getElementById(\"scene\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        bg.setAttribute(\"data-color\", vars.color);\n\n        const termW = view.width * 0.4;\n        const termH = view.height * 0.5;\n\n        function terminal(title, text) {\n          const node = document.createElement(\"div\");\n          node.className = \"term\";\n          node.style.width = termW + \"px\";\n          node.style.height = termH + \"px\";\n          node.style.borderColor = vars.color;\n          const bar = document.createElement(\"div\");\n          bar.className = \"term-bar\";\n          [\"#ff5f56\", \"#ffbd2e\", \"#27c93f\"].forEach(function (hex) {\n            const dot = document.createElement(\"div\");\n            dot.className = \"term-dot\";\n            dot.style.backgroundColor = hex;\n            bar.append(dot);\n          });\n          const label = document.createElement(\"div\");\n          label.className = \"term-title\";\n          label.textContent = title;\n          bar.append(label);\n          const body = document.createElement(\"pre\");\n          body.className = \"term-body\";\n          body.style.whiteSpace = \"pre\";\n          body.style.color = vars.color;\n          body.style.fontSize = view.vmin * 3 + \"px\";\n          const typed = document.createElement(\"span\");\n          typed.textContent = text;\n          const cursor = document.createElement(\"span\");\n          cursor.className = \"cursor\";\n          cursor.textContent = \" \";\n          cursor.style.backgroundColor = vars.color;\n          body.append(typed, cursor);\n          node.append(bar, body);\n          node.setAttribute(\"data-layout-allow-overlap\", \"\");\n          node.setAttribute(\"data-layout-allow-occlusion\", \"\");\n          return { node: node, typed: typed, cursor: cursor };\n        }\n\n        const command = String(vars.command);\n        const one = terminal(\"user@dev:~/project\", \"$ \" + command + \"\\nOn branch main\\nworking tree clean\");\n        const two = terminal(\"server-logs\", \"[INFO] Server started on port 3000\\n[INFO] Connected to database\\n[WARN] High memory usage\");\n        const three = terminal(\"build-process\", \"> build project\\n> transpile modules\\n> optimize assets\\nBuild successful\");\n\n        const scene = hyperbits.createScene3D(sceneEl, {\n          perspective: 1000,\n          transitionDuration: 1.15,\n          easing: \"easeInOutCubic\",\n          steps: [\n            { id: \"main\", x: 0, y: 0, z: 0, rotateY: -6, duration: 3.4, element: one.node },\n            { id: \"side\", x: view.vmin * 58, y: 0, z: view.vmin * 18, rotateY: -22, duration: 3.3, element: two.node },\n            { id: \"top\", x: view.vmin * 58, y: -view.vmin * 42, z: view.vmin * 18, rotateX: 8, duration: 3.3, element: three.node },\n          ],\n        });\n        sceneEl.style.position = \"absolute\";\n        sceneEl.style.inset = \"0\";\n        sceneEl.style.zIndex = \"1\";\n\n        const writers = [\n          hyperbits.typewriter(one.typed, { duration: 2.4, delay: 0.2 }),\n          hyperbits.typewriter(two.typed, { duration: 2.4, delay: 3.5 }),\n          hyperbits.typewriter(three.typed, { duration: 2.4, delay: 6.8 }),\n        ];\n        const proxy = { time: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        scene.bind(timeline);\n        timeline.to(proxy, {\n          time: 10,\n          duration: 10,\n          ease: \"none\",\n          onUpdate: function () {\n            writers.forEach(function (writer) { writer.apply(proxy.time); });\n          },\n        }, 0);\n        timeline.fromTo([one.cursor, two.cursor, three.cursor], { opacity: 1 }, { opacity: 0.15, duration: 0.45, repeat: 21, yoyo: true, ease: \"none\" }, 0);\n        registerTimeline(\"terminal-3d\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
