    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Card color\",\"default\":\"#9a3412\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#1c140d\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1080, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #1c140d;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1080px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #1c140d;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        perspective: 1200px;\n      }\n      #stack {\n        position: relative;\n        transform-style: preserve-3d;\n        z-index: 1;\n      }\n      .card {\n        position: absolute;\n        inset: 0;\n        border-radius: 2.2vmin;\n        border: 0.4vmin solid rgba(255, 255, 255, 0.12);\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        font-weight: 800;\n        font-size: 16vmin;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"card-stack\"\n      data-start=\"0\"\n      data-duration=\"4\"\n      data-width=\"1080\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"4\" style=\"position:absolute;inset:0;background-color:#1c140d\"></div>\n      <div id=\"stack\" class=\"clip\" data-start=\"0\" data-duration=\"4\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const stack = document.getElementById(\"stack\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        const cardWidth = view.vmin * 42;\n        const cardHeight = cardWidth * 1.5;\n        stack.style.width = cardWidth + \"px\";\n        stack.style.height = cardHeight + \"px\";\n        const count = 8;\n        for (let index = 0; index < count; index += 1) {\n          const card = document.createElement(\"div\");\n          card.className = \"card\";\n          card.setAttribute(\"data-layout-allow-overlap\", \"\");\n          card.setAttribute(\"data-layout-allow-occlusion\", \"\");\n          const even = index % 2 === 0;\n          card.style.backgroundColor = even ? vars.color : \"#3f2a14\";\n          card.style.color = \"#f8fafc\";\n          card.style.textShadow = \"0 2px 8px rgba(0,0,0,0.55)\";\n          card.style.zIndex = String(-index);\n          card.style.borderRadius = view.vmin * 2.2 + \"px\";\n          card.style.fontSize = cardWidth * 0.4 + \"px\";\n          card.textContent = String(index + 1);\n          stack.append(card);\n        }\n        const cards = Array.from(stack.children);\n        const timeline = gsap.timeline({ paused: true });\n        cards.forEach(function (card, index) {\n          const angle = (index - (count - 1) / 2) * 8;\n          const xOffset = (index - (count - 1) / 2) * view.vmin * 5.5;\n          timeline.fromTo(\n            card,\n            { y: view.vmin * 80, rotate: 0, x: 0 },\n            { y: 0, x: xOffset, rotate: angle, duration: 50 / 30, ease: \"power3.out\" },\n            index * 3 / 30,\n          );\n        });\n        registerTimeline(\"card-stack\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
