" data-start=\"0\" data-duration=\"3\" style=\"position:absolute;inset:0;background-color:#09090b\"></div>\n      <div id=\"grid\" class=\"clip\" data-start=\"0\" data-duration=\"3\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const grid = document.getElementById(\"grid\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        const cols = 4;\n        const gap = view.vmin * 2;\n        const padding = view.vmin * 8;\n        const available = Math.min(view.width, view.height) - padding * 2 - gap * (cols - 1);\n        const itemSize = available / cols;\n        grid.style.gridTemplateColumns = \"repeat(4, \" + itemSize + \"px)\";\n        grid.style.gridTemplateRows = \"repeat(4, \" + itemSize + \"px)\";\n        grid.style.gap = gap + \"px\";\n        for (let index = 0; index < 16; index += 1) {\n          const cell = document.createElement(\"div\");\n          cell.className = \"cell\";\n          cell.textContent = String(index + 1);\n          cell.style.backgroundColor = vars.color;\n          cell.style.borderRadius = itemSize * 0.22 + \"px\";\n          cell.style.fontSize = itemSize * 0.3 + \"px\";\n          grid.append(cell);\n        }\n        const timeline = gsap.timeline({ paused: true });\n        hyperbits.stagger(grid.children, { scale: [0, 1], opacity: [0, 1], duration: 1.5, stagger: 3 / 30, staggerDirection: \"center\", ease: \"spring\" }, timeline);\n        registerTimeline(\"grid-stagger\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
