    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"command\",\"type\":\"string\",\"label\":\"Command\",\"default\":\"npm install hyperbits\"},{\"id\":\"color\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#4ec9b0\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#0b1220\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #0b1220;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #0b1220;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: \"JetBrains Mono\", ui-monospace, monospace;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        color: #d4d4d4;\n      }\n      #term {\n        width: 70%;\n        height: 70%;\n        background-color: #1e1e1e;\n        border: 1px solid #334155;\n        border-radius: 18px;\n        padding: 4.5vmin 4vmin;\n        font-size: 3.5vmin;\n        line-height: 1.55;\n        position: relative;\n        z-index: 1;\n        overflow: hidden;\n        box-shadow: 0 24px 80px rgba(0, 0, 0, 0.4);\n      }\n      .row {\n        display: block;\n        white-space: pre;\n      }\n      .ok {\n        color: #4ec9b0;\n      }\n      .path {\n        color: #569cd6;\n      }\n      .cmd {\n        color: #ce9178;\n      }\n      .out {\n        color: #d4d4d4;\n        white-space: pre;\n        display: block;\n      }\n      #cursor {\n        display: inline-block;\n        width: 0.55em;\n        height: 1em;\n        margin-left: 0.12em;\n        background-color: #d4d4d4;\n        vertical-align: -0.12em;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"cli-simulation\"\n      data-start=\"0\"\n      data-duration=\"15\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"15\" style=\"position:absolute;inset:0;background-color:#0b1220\"></div>\n      <div id=\"term\" class=\"clip\" data-start=\"0\" data-duration=\"15\">\n        <div class=\"row\">\n          <span id=\"prompt\" class=\"ok\">$</span>\n          <span class=\"path\"> ~ </span>\n          <span id=\"typed\" class=\"cmd\"></span><span id=\"cursor\"></span>\n        </div>\n        <div id=\"output\"></div>\n      </div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const term = document.getElementById(\"term\");\n        const promptEl = document.getElementById(\"prompt\");\n        const typed = document.getElementById(\"typed\");\n        const cursor = document.getElementById(\"cursor\");\n        const outputEl = document.getElementById(\"output\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        promptEl.style.color = vars.color;\n        promptEl.setAttribute(\"data-color\", vars.color);\n        cursor.style.backgroundColor = vars.color;\n        term.style.fontSize = view.vmin * 3.5 + \"px\";\n        const command = String(vars.command);\n        typed.textContent = command;\n        const commandWriter = hyperbits.typewriter(typed, { duration: 3.2, delay: 0.2 });\n        const logs = [\"Package found\", \"Dependencies resolved\", \"Installing...\", \"Done in 1.4s\"];\n        const outputLines = [];\n        for (let index = 0; index < logs.length; index += 1) {\n          const line = document.createElement(\"div\");\n          line.className = \"out\";\n          line.textContent = logs[index];\n          line.style.opacity = \"0\";\n          if (index === logs.length - 1) line.style.color = vars.color;\n          outputEl.append(line);\n          outputLines.push(line);\n        }\n        const proxy = { time: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, {\n          time: 15,\n          duration: 15,\n          ease: \"none\",\n          onUpdate: function () {\n            commandWriter.apply(proxy.time);\n          },\n        }, 0);\n        timeline.fromTo(cursor, { opacity: 1 }, { opacity: 0, duration: 0.4, repeat: 8, yoyo: true, ease: \"none\" }, 0);\n        timeline.to(cursor, { opacity: 0, duration: 0.01 }, 3.5);\n        for (let index = 0; index < outputLines.length; index += 1) {\n          timeline.fromTo(\n            outputLines[index],\n            { opacity: 0, y: 10 },\n            { opacity: 1, y: 0, duration: 0.35, ease: \"power2.out\" },\n            3.6 + index * 0.7,\n          );\n        }\n        registerTimeline(\"cli-simulation\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
