    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"target\",\"type\":\"number\",\"label\":\"Target\",\"default\":1000},{\"id\":\"color\",\"type\":\"color\",\"label\":\"Text color\",\"default\":\"#f8fafc\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#0b1220\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #0b1220;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #0b1220;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n      }\n      #stage {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        z-index: 1;\n      }\n      #value {\n        color: #f8fafc;\n        font-weight: 900;\n        font-variant-numeric: tabular-nums;\n        font-family: \"JetBrains Mono\", ui-monospace, monospace;\n        letter-spacing: 0.04em;\n        line-height: 1;\n        font-size: 14vmin;\n        position: relative;\n        z-index: 2;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"counter-confetti\"\n      data-start=\"0\"\n      data-duration=\"6\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"6\" style=\"position:absolute;inset:0;background-color:#0b1220\"></div>\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"6\"></canvas>\n      <div id=\"value\" class=\"clip\" data-start=\"0\" data-duration=\"6\">0</div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const canvas = document.getElementById(\"stage\");\n        const valueEl = document.getElementById(\"value\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        valueEl.style.color = vars.color;\n        valueEl.setAttribute(\"data-color\", vars.color);\n        valueEl.style.fontSize = view.vmin * 14 + \"px\";\n        valueEl.style.textShadow = \"0 0 \" + view.vmin * 4 + \"px \" + vars.color;\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const counter = hyperbits.createCounter(valueEl, { separator: \",\" });\n        const confettiColors = [\"#FF6B6B\", \"#FFD93D\", \"#6BCB77\", \"#4D96FF\", \"#C084FC\", \"#FF8FA3\", \"#36D399\", \"#FBBD23\"];\n        const simulator = hyperbits.createParticles({\n          fps: 30,\n          spawners: [\n            {\n              id: \"left\",\n              burst: 40,\n              delayFrame: 90,\n              position: { x: view.width * -0.02, y: view.height * 0.5 },\n              area: { width: 0, height: view.height * 0.3 },\n              velocity: { x: view.width * 0.018, y: -view.height * 0.012, varianceX: view.width * 0.008, varianceY: view.height * 0.02 },\n              lifespan: 90,\n              lifespanVariance: 12,\n              max: 40,\n            },\n            {\n              id: \"right\",\n              burst: 40,\n              delayFrame: 90,\n              position: { x: view.width * 1.02, y: view.height * 0.5 },\n              area: { width: 0, height: view.height * 0.3 },\n              velocity: { x: -view.width * 0.018, y: -view.height * 0.012, varianceX: view.width * 0.008, varianceY: view.height * 0.02 },\n              lifespan: 90,\n              lifespanVariance: 12,\n              max: 40,\n            },\n            {\n              id: \"bottom\",\n              burst: 40,\n              delayFrame: 90,\n              position: { x: view.width * 0.5, y: view.height * 1.05 },\n              area: { width: view.width * 0.6, height: 0 },\n              velocity: { x: 0, y: -view.height * 0.032, varianceX: view.width * 0.012, varianceY: view.height * 0.01 },\n              lifespan: 90,\n              lifespanVariance: 12,\n              max: 40,\n            },\n          ],\n          behaviors: [\n            { id: \"gravity\", handler: hyperbits.createGravity({ y: 0.35 }) },\n            { id: \"drag\", handler: hyperbits.createDrag(0.98) },\n            { id: \"fade\", handler: hyperbits.createOpacityOverLife([1, 0]) },\n            {\n              id: \"spin\",\n              handler: function (p) {\n                p.rotation += p.velocity.x * 0.08;\n              },\n            },\n          ],\n        });\n        const timeline = gsap.timeline({ paused: true });\n        timeline.fromTo(\n          counter.proxy,\n          { value: 0 },\n          { value: Number(vars.target) || 1000, duration: 3, ease: \"power2.out\", onUpdate: counter.apply },\n          0,\n        );\n        timeline.fromTo(valueEl, { scale: 0.85, opacity: 0.2 }, { scale: 1, opacity: 1, duration: 0.6, ease: \"power3.out\" }, 0);\n        try {\n          hyperbits.bind(timeline, canvas, simulator, {\n            shape: \"rect\",\n            size: view.vmin * 2.5,\n            glow: 0,\n            color: function (particle) {\n              return confettiColors[particle.index % confettiColors.length];\n            },\n          });\n        } catch (err) {}\n        timeline.to({}, { duration: 6 }, 0);\n        registerTimeline(\"counter-confetti\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
