    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"text\",\"type\":\"string\",\"label\":\"Text\",\"default\":\"SYSTEM ONLINE\"},{\"id\":\"color\",\"type\":\"color\",\"label\":\"Text color\",\"default\":\"#4ade80\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#020617\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #020617;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #020617;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n      }\n      #title {\n        color: #4ade80;\n        font-family: \"JetBrains Mono\", ui-monospace, monospace;\n        font-weight: 700;\n        letter-spacing: 0.12em;\n        font-size: 10vmin;\n        position: relative;\n        z-index: 1;\n        text-align: center;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"glitch-in\"\n      data-start=\"0\"\n      data-duration=\"3\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"3\" style=\"position:absolute;inset:0;background-color:#020617\"></div>\n      <h1 id=\"title\" class=\"clip\" data-start=\"0\" data-duration=\"3\">SYSTEM ONLINE</h1>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const title = document.getElementById(\"title\");\n        const view = hyperbits.viewport(root);\n        const finalText = String(vars.text);\n        bg.style.backgroundColor = vars.background;\n        title.style.color = vars.color;\n        title.setAttribute(\"data-color\", vars.color);\n        title.style.fontSize = view.vmin * 10 + \"px\";\n        title.setAttribute(\"aria-label\", finalText);\n        const glyphs = \"ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789#$%&\";\n        const proxy = { progress: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        function renderGlitch() {\n          const visible = Math.floor(proxy.progress * finalText.length);\n          let output = \"\";\n          for (let index = 0; index < finalText.length; index += 1) {\n            if (index < visible) {\n              output += finalText[index];\n            } else {\n              const pick = hyperbits.randomInt(\"glitch-\" + index + \"-\" + visible, 0, glyphs.length - 1);\n              output += glyphs[pick];\n            }\n          }\n          title.textContent = output;\n        }\n        timeline.fromTo(\n          proxy,\n          { progress: 0 },\n          { progress: 1, duration: 1.5, ease: \"none\", onUpdate: renderGlitch },\n          0,\n        );\n        timeline.fromTo(title, { opacity: 0 }, { opacity: 1, duration: 0.2 }, 0);\n        registerTimeline(\"glitch-in\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
