    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"lines\",\"type\":\"string\",\"label\":\"Lines (pipe separated)\",\"default\":\"First sentence.|Second longer sentence.|Looping...\"},{\"id\":\"color\",\"type\":\"color\",\"label\":\"Text color\",\"default\":\"#f8fafc\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#0f172a\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #0f172a;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #0f172a;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n      }\n      #line {\n        color: #f8fafc;\n        font-family: \"JetBrains Mono\", ui-monospace, monospace;\n        font-weight: 700;\n        font-size: 10vmin;\n        position: relative;\n        z-index: 1;\n        white-space: nowrap;\n      }\n      #cursor {\n        display: inline-block;\n        width: 0.08em;\n        height: 0.9em;\n        margin-left: 0.06em;\n        background-color: #f8fafc;\n        vertical-align: -0.05em;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"multi-text-typewriter\"\n      data-start=\"0\"\n      data-duration=\"10\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"10\" style=\"position:absolute;inset:0;background-color:#0f172a\"></div>\n      <div id=\"line\" class=\"clip\" data-start=\"0\" data-duration=\"10\">\n        <span id=\"typed\"></span><span id=\"cursor\"></span>\n      </div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const line = document.getElementById(\"line\");\n        const typed = document.getElementById(\"typed\");\n        const cursor = document.getElementById(\"cursor\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        line.style.color = vars.color;\n        line.setAttribute(\"data-color\", vars.color);\n        cursor.style.backgroundColor = vars.color;\n        line.style.fontSize = view.vmin * 10 + \"px\";\n        line.setAttribute(\"aria-label\", vars.lines);\n        const sentences = String(vars.lines).split(\"|\");\n        const typeSpeed = 3 / 30;\n        const deleteSpeed = 1 / 30;\n        const pauseAfterType = 40 / 30;\n        const pauseAfterDelete = 20 / 30;\n        function textAt(time) {\n          let cursorTime = time;\n          let sentenceIndex = 0;\n          while (sentenceIndex < 40) {\n            const sentence = sentences[sentenceIndex % sentences.length];\n            const typeDur = sentence.length * typeSpeed;\n            if (cursorTime < typeDur) return sentence.slice(0, Math.max(0, Math.floor(cursorTime / typeSpeed)));\n            cursorTime -= typeDur;\n            if (cursorTime < pauseAfterType) return sentence;\n            cursorTime -= pauseAfterType;\n            const deleteDur = sentence.length * deleteSpeed;\n            if (cursorTime < deleteDur) {\n              const remain = sentence.length - Math.floor(cursorTime / deleteSpeed);\n              return sentence.slice(0, Math.max(0, remain));\n            }\n            cursorTime -= deleteDur;\n            if (cursorTime < pauseAfterDelete) return \"\";\n            cursorTime -= pauseAfterDelete;\n            sentenceIndex += 1;\n          }\n          return \"\";\n        }\n        const proxy = { time: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, {\n          time: 10,\n          duration: 10,\n          ease: \"none\",\n          onUpdate: function () { typed.textContent = textAt(proxy.time); },\n        }, 0);\n        timeline.fromTo(cursor, { opacity: 1 }, { opacity: 0, duration: 0.4, repeat: 24, yoyo: true, ease: \"none\" }, 0);\n        registerTimeline(\"multi-text-typewriter\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
