    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#38bdf8\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#0b1220\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #0b1220;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #0b1220;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n      }\n      #panel {\n        width: 78%;\n        min-height: 54%;\n        background-color: #111827;\n        border: 2px solid #38bdf8;\n        border-radius: 24px;\n        position: relative;\n        z-index: 1;\n        overflow: hidden;\n      }\n      .hyperbits-code {\n        margin: 0;\n        color: #e5e7eb;\n        white-space: pre;\n        font-family: \"JetBrains Mono\", ui-monospace, monospace;\n        font-size: 2.2vw;\n        line-height: 1.5;\n      }\n      .hyperbits-code-line {\n        display: block;\n      }\n      .hyperbits-code-gutter {\n        display: inline-block;\n        width: 3em;\n        color: #64748b;\n      }\n      .token.keyword { color: #c084fc; }\n      .token.function { color: #38bdf8; }\n      .token.string { color: #86efac; }\n      #caret {\n        display: inline-block;\n        width: 0.08em;\n        height: 1em;\n        margin-left: 0.08em;\n        background-color: #38bdf8;\n        vertical-align: -0.1em;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"typing-code-block\"\n      data-start=\"0\"\n      data-duration=\"6\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"6\" style=\"position:absolute;inset:0;background-color:#0b1220\"></div>\n      <div id=\"panel\" class=\"clip\" data-start=\"0\" data-duration=\"6\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const panel = document.getElementById(\"panel\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        panel.style.borderColor = vars.color;\n        panel.setAttribute(\"data-color\", vars.color);\n        panel.style.padding = view.vmin * 4 + \"px \" + view.vmin * 5 + \"px\";\n        panel.style.width = view.vw * 78 + \"px\";\n        const fullCode = \"const App = () => {\\n    const [count, setCount] = useState(0);\\n    useEffect(() => {\\n        document.title = `Count: ${count}`;\\n    }, [count]);\\n    return (\\n        <button onClick={() => setCount(c => c + 1)}>\\n             Clicked {count} times\\n        </button>\\n    );\\n};\";\n        const proxy = { chars: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        function render() {\n          const slice = fullCode.slice(0, Math.floor(proxy.chars));\n          panel.innerHTML = \"\";\n          const block = hyperbits.createCodeBlock(panel, {\n            code: slice,\n            language: \"javascript\",\n            showLineNumbers: true,\n          });\n          block.style.fontSize = view.vw * 1.8 + \"px\";\n          block.style.whiteSpace = \"pre\";\n          block.style.lineHeight = \"1.5\";\n          const functions = panel.querySelectorAll(\".token.function\");\n          for (let index = 0; index < functions.length; index += 1) {\n            functions[index].style.color = vars.color;\n          }\n          const lines = hyperbits.codeLines(block);\n          const lastLine = lines[lines.length - 1];\n          if (lastLine) {\n            const caret = document.createElement(\"span\");\n            caret.id = \"caret\";\n            caret.style.display = \"inline-block\";\n            caret.style.width = \"0.08em\";\n            caret.style.height = \"1em\";\n            caret.style.backgroundColor = vars.color;\n            caret.style.marginLeft = \"0.08em\";\n            caret.style.opacity = Math.floor(timeline.time() * 2.5) % 2 === 0 ? \"1\" : \"0\";\n            lastLine.append(caret);\n          }\n        }\n        timeline.fromTo(\n          proxy,\n          { chars: 0 },\n          { chars: fullCode.length, duration: 5.2, ease: \"none\", onUpdate: render },\n          0.2,\n        );\n        timeline.to({}, { duration: 6 }, 0);\n        registerTimeline(\"typing-code-block\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
