    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"text\",\"type\":\"string\",\"label\":\"Text\",\"default\":\"Typing with errors and variable speed...\"},{\"id\":\"color\",\"type\":\"color\",\"label\":\"Text color\",\"default\":\"#ff6b6b\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#0f172a\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #0f172a;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #0f172a;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n      }\n      #line {\n        color: #ff6b6b;\n        font-family: \"JetBrains Mono\", ui-monospace, monospace;\n        font-weight: 700;\n        max-width: 86%;\n        font-size: 10vmin;\n        position: relative;\n        z-index: 1;\n      }\n      #cursor {\n        display: inline-block;\n        width: 0.08em;\n        height: 0.9em;\n        margin-left: 0.06em;\n        background-color: #ff6b6b;\n        vertical-align: -0.05em;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"variable-speed-typewriter\"\n      data-start=\"0\"\n      data-duration=\"13.33\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"13.33\" style=\"position:absolute;inset:0;background-color:#0f172a\"></div>\n      <div id=\"line\" class=\"clip\" data-start=\"0\" data-duration=\"13.33\">\n        <span id=\"typed\"></span><span id=\"cursor\"></span>\n      </div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const line = document.getElementById(\"line\");\n        const typed = document.getElementById(\"typed\");\n        const cursor = document.getElementById(\"cursor\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        line.style.color = vars.color;\n        line.setAttribute(\"data-color\", vars.color);\n        cursor.style.backgroundColor = vars.color;\n        line.style.fontSize = view.vmin * 10 + \"px\";\n        line.setAttribute(\"aria-label\", vars.text);\n        const target = String(vars.text);\n        const events = [];\n        let output = \"\";\n        let timeCursor = 0.3;\n        const wrongGlyphs = \"abcdefghijklmnopqrstuvwxyz\";\n        for (let index = 0; index < target.length; index += 1) {\n          const progress = index / Math.max(1, target.length - 1);\n          const speed = hyperbits.interpolate(progress, [0, 0.5, 1], [2, 10, 2]) / 30;\n          const willErr = hyperbits.random(\"err-\" + index) < 0.1 && target[index] !== \" \";\n          if (willErr) {\n            const wrong = wrongGlyphs[hyperbits.randomInt(\"w-\" + index, 0, wrongGlyphs.length - 1)];\n            output += wrong;\n            events.push({ time: timeCursor, text: output });\n            timeCursor += 10 / 30;\n            output = output.slice(0, -1);\n            events.push({ time: timeCursor, text: output });\n            timeCursor += speed;\n          }\n          output += target[index];\n          events.push({ time: timeCursor, text: output });\n          timeCursor += speed;\n        }\n        function textAt(time) {\n          let current = \"\";\n          for (const event of events) {\n            if (event.time <= time) current = event.text;\n          }\n          return current;\n        }\n        const proxy = { time: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, {\n          time: 13.33,\n          duration: 13.33,\n          ease: \"none\",\n          onUpdate: function () { typed.textContent = textAt(proxy.time); },\n        }, 0);\n        timeline.fromTo(cursor, { opacity: 1 }, { opacity: 0, duration: 20 / 30, repeat: 20, yoyo: true, ease: \"none\" }, 0);\n        registerTimeline(\"variable-speed-typewriter\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
