    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"text\",\"type\":\"string\",\"label\":\"Text\",\"default\":\"This appears word by word\"},{\"id\":\"color\",\"type\":\"color\",\"label\":\"Text color\",\"default\":\"#f8fafc\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#0f172a\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #0f172a;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #0f172a;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n      }\n      #title {\n        color: #f8fafc;\n        font-weight: 700;\n        max-width: 80%;\n        text-align: center;\n        letter-spacing: -0.03em;\n        font-size: 10vmin;\n        position: relative;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"word-by-word\"\n      data-start=\"0\"\n      data-duration=\"4\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"4\" style=\"position:absolute;inset:0;background-color:#0f172a\"></div>\n      <h1 id=\"title\" class=\"clip\" data-start=\"0\" data-duration=\"4\">This appears word by word</h1>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const title = document.getElementById(\"title\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        title.textContent = vars.text;\n        title.style.color = vars.color;\n        title.setAttribute(\"data-color\", vars.color);\n        title.style.fontSize = view.vmin * 10 + \"px\";\n        const words = hyperbits.splitText(title, \"words\");\n        const timeline = gsap.timeline({ paused: true });\n        hyperbits.stagger(\n          words,\n          {\n            opacity: [0, 1],\n            y: [view.vmin * 1.8, 0],\n            duration: 0.45,\n            stagger: 3 / 30,\n            ease: \"easeOutQuad\",\n          },\n          timeline,\n        );\n        registerTimeline(\"word-by-word\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
